<?php require 'includes/functions.php'; require_customer(); $customer=current_customer(); $items=cart_items(); if(!$items) redirect('cart.php'); $tot=cart_totals(); $pageTitle='Checkout'; require 'includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $invoice='VM-'.date('Ymd').'-'.rand(1000,9999); $pdo->beginTransaction();
  $stmt=$pdo->prepare('INSERT INTO orders (user_id, invoice_no, customer_name, customer_contact, customer_address, subtotal, service_fee, total_amount, payment_method, payment_status, status, order_notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');
  $stmt->execute([$customer['id'],$invoice,$_POST['customer_name'],$_POST['customer_contact'],$_POST['customer_address'],$tot['subtotal'],$tot['fee'],$tot['total'],$_POST['payment_method'],'Unpaid','Pending',$_POST['order_notes']]); $orderId=$pdo->lastInsertId();
  foreach($items as $it){ $line=$it['price']*$it['qty']; $pdo->prepare('INSERT INTO order_items (order_id, product_id, product_name, quantity, unit_price, line_total, custom_notes) VALUES (?,?,?,?,?,?,?)')->execute([$orderId,$it['id'],$it['name'],$it['qty'],$it['price'],$line,$it['notes']]); $pdo->prepare('UPDATE products SET stock=GREATEST(stock-?,0), sold_count=sold_count+? WHERE id=?')->execute([$it['qty'],$it['qty'],$it['id']]); $pdo->prepare('INSERT INTO inventory (product_id, movement_type, quantity, remarks) VALUES (?,?,?,?)')->execute([$it['id'],'Stock Out',$it['qty'],'Order '.$invoice]); }
  $pdo->prepare('INSERT INTO payments (order_id, method, amount, status) VALUES (?,?,?,?)')->execute([$orderId,$_POST['payment_method'],$tot['total'],'Unpaid']); $pdo->prepare('INSERT INTO sales (order_id, total_amount, sale_date) VALUES (?,?,CURDATE())')->execute([$orderId,$tot['total']]); upload_design_file('design_file',$orderId,null); $pdo->commit(); unset($_SESSION['cart']); $_SESSION['flash']='Order placed successfully. Track it from your dashboard.'; redirect('invoice.php?id='.$orderId); }
?>
<main class="section-pad"><div class="container"><h1 class="fw-bold mb-4">Checkout</h1><form method="post" enctype="multipart/form-data" class="row g-4"><div class="col-lg-7"><div class="p-4 rounded-4 shadow-sm"><h4>Customer Information</h4><input name="customer_name" class="form-control mb-3" value="<?= e($customer['name']) ?>" required><input name="customer_contact" class="form-control mb-3" value="<?= e($customer['phone']) ?>" required><textarea name="customer_address" class="form-control mb-3" required><?= e($customer['address']) ?></textarea><label class="form-label">Upload PNG, JPG, PDF, PSD, or DOCX</label><input name="design_file" type="file" class="form-control mb-3" accept=".png,.jpg,.jpeg,.pdf,.psd,.docx"><textarea name="order_notes" class="form-control mb-3" placeholder="Order notes" rows="3"></textarea><label class="form-label">Payment method</label><select name="payment_method" class="form-select"><option>Cash on Pickup</option><option>GCash</option></select></div></div><div class="col-lg-5"><div class="p-4 rounded-4 shadow-sm"><h4>Order Summary</h4><?php foreach($items as $it): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($it['name']) ?> x <?= $it['qty'] ?></span><b><?= money($it['price']*$it['qty']) ?></b></div><?php endforeach; ?><p class="mt-3">Subtotal: <b><?= money($tot['subtotal']) ?></b></p><p>Service fee: <b><?= money($tot['fee']) ?></b></p><h3>Total: <?= money($tot['total']) ?></h3><button class="btn btn-red btn-lg w-100 mt-3">Place Order</button></div></div></form></div></main><?php require 'includes/footer.php'; ?>